l.classList.remove('show')\n      modal.setAttribute('aria-hidden', 'true')\n      modal.style.display = 'none'\n      isModalOpen.value = false\n    }\n\n    const reset = () => {\n      themeStore.resetToDefaults()\n    }\n\n    const importTheme = () => {\n      fileInput.value.click()\n    }\n\n    const handleFileSelect = (event) => {\n      const file = event.target.files[0]\n      if (!file) return\n\n      const reader = new FileReader()\n      reader.onload = (e) => {\n        try {\n          const jsonData = JSON.parse(e.target.result)\n          \n          if (typeof jsonData !== 'object' || jsonData === null || !jsonData.hasOwnProperty('theme')) {\n            alert(i18next.t('simulator:themeModal.import.error'))\n            return\n          }\n\n          const sceneObject = JSON.parse(app.editor.lastActionJson)\n          sceneObject.theme = jsonData.theme\n          app.editor.loadJSON(JSON.stringify(sceneObject))\n          app.editor.onActionComplete()\n          jsonEditorService.updateContent(app.editor.lastActionJson);\n          \n        } catch (error) {\n          console.error(error)\n          alert(i18next.t('simulator:themeModal.import.error'))\n        }\n      }\n      \n      reader.onerror = () => {\n        alert(i18next.t('simulator:themeModal.import.error'))\n      }\n      \n      reader.readAsText(file)\n      \n      // Reset the file input\n      event.target.value = ''\n    }\n\n    return {\n      isModalOpen,\n      closeModal,\n      reset,\n      tooltipType,\n      fileInput,\n      importTheme,\n      handleFileSelect\n    }\n  }\n}\n</script>\n\n<style scoped>\n.modal-backdrop {\n  position: fixed;\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 100%;\n  background-color: rgba(0, 0, 0, 0.3);\n  z-index: 1040;\n}\n\n.modal-backdrop.show {\n  opacity: 1;\n}\n\n.modal-dialog {\n  z-index: 1045;\n}\n\n.theme-modal-body {\n  max-height: 70vh;\n  overflow-y: auto;\n  padding-right: 8px;\n}\n</style> "],"sourceRoot":""}]