#toolbar, #toolbar-mobile {
  padding-top: 7px;
  padding-bottom: 3px;
  padding-left: 7px;
  padding-right: 7px;
}
#toolbar {
  backdrop-filter: blur(2px);
  -webkit-backdrop-filter: blur(2px);
}
#toolbar-mobile {
}
#non-toolbar-space {
  position: relative;
  flex-grow: 1;
}
.mobile-dropdown-menu {
  height: 0;
  transition: height .3s ease;
  overflow: hidden;

  top: 100%;
  left: 0;
  right: 0;
  margin: 0 !important;
  padding: 0;  
  overflow: hidden; 
  
  border: none;
  border-radius: 0;
}
#mobile-dropdown-collpase {
  position: absolute;
  top: 0;
  width: 100%;

  height: 0;
  transition: height .3s ease;
}
.range-minus-btn {
  padding-left: 0px;
  padding-right: 7px;
}
.range-plus-btn {
  padding-left: 7px;
  padding-right: 0px;
}
.settings-number {
  background-color: transparent;
  border: none;
  border-bottom: 1px solid rgba(0, 0, 0, 0.5);
  width: 40px;
  text-align: center;
}
.settings-label {
  padding-right: 0px;
}
#more-options-dropdown {
  min-width: 300px;
  width: max-content;
  max-height: 80vh;
  overflow-y: auto;
}
#mobile-dropdown-options .container {
  max-height: 75vh;
  overflow-y: auto;
}
#mobile-dropdown-options .row {
  padding-top: 0;
  padding-bottom: 0;
}
#mobile-dropdown-options .form-check-input {
  height: 1.2em;
  width: 2.4em;
}
.settings-control-row {
  min-height: 30px;
}

/* Shared disabled look for settings value controls (number fields, Color mode popup, etc.) */
#more-options-dropdown .settings-control-value--disabled:disabled,
#mobile-dropdown-options .settings-control-value--disabled:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  color: var(--bs-secondary-color, #6c757d);
}
#more-options-dropdown button.settings-control-value--disabled:disabled,
#mobile-dropdown-options button.settings-control-value--disabled:disabled {
  /* Bootstrap disables pointer events; re-enable so the not-allowed cursor shows */
  pointer-events: auto;
  color: var(--bs-secondary-color, #6c757d) !important;
  background-color: transparent !important;
  border: none !important;
  box-shadow: none;
}
#more-options-dropdown input.settings-control-value--disabled:disabled,
#mobile-dropdown-options input.settings-control-value--disabled:disabled {
  box-shadow: none;
}
